<?php

use Illuminate\Support\Facades\Route;
use App\Http\Controllers\{AuthController, CustomerPortalController, OperationsController};

Route::get('/', [CustomerPortalController::class, 'home'])->name('home');
Route::middleware('guest')->group(function(){ Route::get('/login',[AuthController::class,'create'])->name('login'); Route::get('/admin/login', fn () => redirect()->route('login'))->name('admin.login'); Route::post('/login',[AuthController::class,'store']); Route::get('/register',[AuthController::class,'registerForm'])->name('register'); Route::post('/register',[AuthController::class,'register']); });
Route::middleware('auth')->group(function(){ Route::get('/customer/dashboard',[CustomerPortalController::class,'dashboard'])->name('customer.dashboard'); Route::get('/appointments',[CustomerPortalController::class,'createAppointment'])->name('appointments.create'); Route::post('/appointments',[CustomerPortalController::class,'storeAppointment'])->name('appointments.store'); Route::post('/logout',[AuthController::class,'destroy'])->name('logout'); });
Route::middleware(['auth', 'management'])->prefix('admin')->group(function(){ Route::get('/dashboard',[OperationsController::class,'dashboard'])->name('dashboard'); Route::get('/customers',[OperationsController::class,'customers'])->name('customers.index'); Route::post('/customers',[OperationsController::class,'storeCustomer'])->name('customers.store'); Route::patch('/customers/{customer}',[OperationsController::class,'updateCustomer'])->name('customers.update'); Route::delete('/customers/{customer}',[OperationsController::class,'deleteCustomer'])->name('customers.delete'); Route::get('/jobs',[OperationsController::class,'jobs'])->name('jobs.index'); Route::post('/jobs',[OperationsController::class,'storeJob'])->name('jobs.store'); Route::patch('/jobs/{job}',[OperationsController::class,'updateJob'])->name('jobs.update'); Route::delete('/jobs/{job}',[OperationsController::class,'deleteJob'])->name('jobs.delete'); Route::patch('/jobs/{job}/status',[OperationsController::class,'updateJobStatus'])->name('jobs.status'); Route::post('/technicians',[OperationsController::class,'storeTechnician'])->name('technicians.store'); Route::delete('/technicians/{user}',[OperationsController::class,'deleteTechnician'])->name('technicians.delete'); Route::get('/inventory',[OperationsController::class,'inventory'])->name('inventory.index'); Route::post('/inventory',[OperationsController::class,'storeInventory'])->name('inventory.store'); Route::patch('/inventory/{item}',[OperationsController::class,'updateInventory'])->name('inventory.update'); Route::delete('/inventory/{item}',[OperationsController::class,'deleteInventory'])->name('inventory.delete'); Route::get('/invoices',[OperationsController::class,'invoices'])->name('invoices.index'); Route::get('/invoices/export',[OperationsController::class,'exportInvoices'])->name('invoices.export'); Route::patch('/invoices/{invoice}',[OperationsController::class,'updateInvoice'])->name('invoices.update'); Route::delete('/invoices/{invoice}',[OperationsController::class,'deleteInvoice'])->name('invoices.delete'); Route::post('/invoices/{invoice}/pay',[OperationsController::class,'pay'])->name('invoices.pay'); Route::patch('/commissions/{commission}',[OperationsController::class,'updateCommission'])->name('commissions.update'); Route::delete('/commissions/{commission}',[OperationsController::class,'deleteCommission'])->name('commissions.delete'); Route::get('/reports',[OperationsController::class,'reports'])->name('reports.index'); });
use Illuminate\Support\Facades\Artisan;

Route::get('/fix-routes', function () {
    Artisan::call('route:clear');
    Artisan::call('config:clear');
    Artisan::call('cache:clear');
    return 'Routes and cache cleared successfully!';
});
